    /** رسم أيقونة SVG inline */
    public static function render(string $name, string $class = 'h-4 w-4', ?string $style = null): string
    {
        $icons = static::all();
        $inner = $icons[$name] ?? $icons['alert-circle'];

        return sprintf(
            '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="%s"%s aria-hidden="true">%s</svg>',
            $class,
            $style ? ' style="'.$style.'"' : '',
            $inner
        );
    }

    /** خريطة أيقونات أجهزة من الاسم */
    public static function device(string $deviceName): string
    {
        $map = [
            'تكييف' => 'wind', 'سبليت' => 'wind', 'مروحة' => 'fan', 'مكيف' => 'wind',
            'غسالة' => 'washer', 'غسالات' => 'washer', 'نشافة' => 'washer',
            'ثلاجة' => 'fridge', 'ديب فريزر' => 'fridge', 'فريزر' => 'fridge',
            'بوتاجاز' => 'flame', 'فرن' => 'flame', 'سخان' => 'flame',
            'شاشة' => 'tv', 'تلفزيون' => 'tv',
            'دش' => 'dish', 'رسيفر' => 'dish', 'كاميرا' => 'camera',
            'أخرى' => 'wrench', 'اخرى' => 'wrench',
        ];

        return $map[trim($deviceName)] ?? 'wrench';
    }
